import {readFileSync, readdirSync, existsSync} from 'node:fs';
import {resolve, join, extname} from 'node:path';

// Validate the actual Pages upload directory, including HTML generated by the
// deployment workflow. Media/photos and official logo files are intentionally
// excluded: this rule applies to application interface colors.
const allowed=new Set(['#0A1B2E','#102B40','#173750','#204158','#F3F8FC','#ABC6D7','#355E72','#60F1AD']);
const root=resolve(process.argv[2]||'.pages-output');
const files=[];
for(const dir of ['', 'beta', 'privacy', 'terms']){
 const abs=join(root,dir);
 if(!existsSync(abs))continue;
 for(const e of readdirSync(abs,{withFileTypes:true})){
  if(!e.isFile()||!/\.(?:html|css|js|mjs|webmanifest)$/.test(e.name))continue;
  files.push(join(abs,e.name));
 }
}
if(!files.length)throw Error('No Pages interface assets found in '+root);
let total=0;
for(const file of files){
 const src=readFileSync(file,'utf8');
 const matches=[...src.matchAll(/#(?:[0-9a-f]{8}|[0-9a-f]{6}|[0-9a-f]{4}|[0-9a-f]{3})(?![\w-])/gi)];
 for(const m of matches){
  total++;
  if(!allowed.has(m[0].toUpperCase())){
   const line=src.slice(0,m.index).split('\n').length;
   throw Error('Unapproved UI color '+m[0]+' in '+file+':'+line);
  }
 }
 const rgb=/\b(?:rgba?|hsla?)\s*\(/gi.exec(src);
 if(rgb)throw Error('Unexpected direct RGB/HSL color in '+file+': '+rgb[0]);
}
const html=readFileSync(join(root,'index.html'),'utf8');
if(!html.includes('20261122-approved-seven-palette-v3'))throw Error('Missing cache-busted release marker');
/* Mint is a deliberate eighth color, not a reason to re-enable warm/cream UI
   colors. Verify the places which used #60F1AD before palette consolidation. */
const mintFiles=[
 ['index.html',7],
 ['doweo-reference-home.css',3],
 ['doweo-cashflow-analytics.js',1],
];
for(const [name,expected] of mintFiles){
 const contents=readFileSync(join(root,name),'utf8');
 const actual=(contents.match(/#60F1AD/gi)||[]).length;
 if(actual<expected)throw Error(name+' lost original mint accents: expected '+expected+', found '+actual);
}
if(!html.includes('--dw-mobile-accent:#60F1AD;')||
   !html.includes('--accent:#60F1AD;')||
   !html.includes('button[data-mh-action="sq-clean-settle"] {\\n    background:#60F1AD!important;')) {
 throw Error('Mobile theme or Settle Up lost the original mint color');
}
if(!html.includes('doweo-reference-home.css?v=20261122-original-mint-v1')||
   !html.includes('doweo-cashflow-analytics.js?v=20261122-original-mint-v1')) {
 throw Error('Fresh mint CSS/JS version missing; cached assets could hide mint');
}
console.log('Approved navy-and-mint eight-color palette verified in '+files.length+' deployed files, '+total+' color literals checked');
